19	// assertPlanStillOpen 是日期不符等拒绝后的统一核对：计划仍未完成、留在待办，
20	// 没有写入完成时间或关联证书。
21	func assertPlanStillOpen(t *testing.T, l *Ledger, number string) {
22		t.Helper()
23		p := l.findPlan(number)
24		if p == nil {
25			t.Fatalf("计划 %s 应仍然存在", number)
26		}
27		if p.Status != PlanStatusOpen {
