29		}
30		if p.CompletedAt != "" || p.CertificateNumber != "" {
31			t.Fatalf("被拒绝后不应写入完成时间或关联证书：%+v", p)
32		}
33		items, err := l.Todos(p.InstrumentID)
34		if err != nil {
35			t.Fatalf("todos: %v", err)
36		}
37		if len(items) != 1 || items[0].PlanNumber != number {
38			t.Fatalf("计划 %s 应继续留在待办，得到 %+v", number, items)
39		}
40	}
