42	// assertCertAndInstrumentUnchanged 核对完成动作只结束计划：不更改器具允许误差、
43	// 状态，也不更改两张证书的测得误差与有效期。
44	func assertCertAndInstrumentUnchanged(t *testing.T, l *Ledger, want map[string]Certificate) {
45		t.Helper()
