55		}
56		for number, w := range want {
57			got := l.findCertificate(number)
58			if got == nil {
59				t.Fatalf("证书 %s 不应丢失", number)
60			}
61			if got.Error != w.Error || got.Expiry != w.Expiry || got.CalDate != w.CalDate {
62				t.Fatalf("证书 %s 不应被完成动作改动：得到 %+v， want %+v", number, got, w)
63			}
64		}
65	}
