212	// TestHistoricalFailingCertCompletesButNewerPassingCertStillGovernsUse 保住相反
213	// 结论：较早证书超差、较新证书合格且未到期，器具在用。较早的超差证书同样可以
214	// 完成符合条件的计划；核对与使用申请仍以较新证书为准，申请获准并留痕。完成动作
215	// 不更改器具允许误差、状态、两张证书的测得误差或有效期。
216	func TestHistoricalFailingCertCompletesButNewerPassingCertStillGovernsUse(t *testing.T) {
