241		if err != nil {
242			t.Fatalf("add first: %v", err)
243		}
244		// 再次提交同号且全部业务字段一致：返回原证书内容，不增加历史。
245		again, dup, err := l.AddCertificate(in)
246		if err != nil || !dup {
247			t.Fatalf("幂等提交应成功并标记 duplicate，err=%v dup=%v", err, dup)
248		}
249		if *again != *first {
250			t.Fatalf("幂等提交应返回原证书内容：首次 %+v，再次 %+v", *first, *again)
251		}
252		if n := len(l.certificatesOf("M-1")); n != 1 {
253			t.Fatalf("历史证书不应增加，得到 %d 张", n)
254		}
255	
256		// 同号内容不同：报冲突且不改动已有数据（换器具也算不同）。
257		conflict := in
258		conflict.Error = 0.2
259		if _, _, err := l.AddCertificate(conflict); !IsConflict(err) {
260			t.Fatalf("同号不同内容应报冲突，得到 %v", err)
261		}
262		conflict2 := in
263		conflict2.InstrumentID = "M-2"
264		if _, _, err := l.AddCertificate(conflict2); !IsConflict(err) {
265			t.Fatalf("同号挂到不同器具应报冲突，得到 %v", err)
266		}
267		got := l.findCertificate("C-1")
268		if got.InstrumentID != "M-1" || got.Error != 0.1 {
269			t.Fatalf("冲突后已有数据被改动：%+v", got)
270		}
