func TestCreatePlanSingleTimestampAcrossMidnight(t *testing.T) {
	day3late := time.Date(2026, 10, 3, 23, 59, 59, 0, time.Local)
	day4 := time.Date(2026, 10, 4, 0, 0, 5, 0, time.Local)

	clock := &fakeClock{t: mustDate(t, "2026-10-03")}
