11		"github.com/bengzyyys/calibration-ledger/calibrate"
12	)
13	
14	// 本文件从命令行端到端守住“用历史证书完成校准计划”：
15	//
16	//	计划关联证书（哪一张证书结束了当时建立的计划）与器具最近证书（按校准日期
17	//	决定能否使用）是两件事。较早、非最近的证书同样可以完成计划，但核对与使用
18	//	申请始终只认最近证书。
19	//
20	// 命令行使用真实本机时钟，无法把计划建立时刻倒拨到过去，因此这里预置一张
21	// 含“较早建立的未完成计划”的台账文件，再通过真实命令录入两张不同校准日期的
22	// 证书并完成计划；所有日期相对运行当天动态计算，保证两张证书截止日都晚于
23	// 核对当天、校准日期不晚于当天且不早于计划建立日。
24	
25	// seedOldPlanLedger 在 path 写入一件在用器具和一项建立于 createdAgoDays 天前、
26	// 计划日期在未来的未完成计划。证书留空，由测试随后用真实命令录入。
27	func seedOldPlanLedger(t *testing.T, path string, createdAgoDays int) {
28		t.Helper()
29		now := time.Now()
30		createdAt := now.AddDate(0, 0, -createdAgoDays).Format(time.RFC3339)
31		data := map[string]any{
32			"version": 1,
33			"instruments": []map[string]any{{
34				"id": "M-1", "name": "万用表", "allowed_error": 0.5,
35				"status":        string(calibrate.StatusInUse),
36				"registered_at": createdAt,
37			}},
38			"certificates": []any{},
39			"usage":        []any{},
40			"plans": []map[string]any{{
41				"number": "PL-1", "instrument_id": "M-1",
42				"planned_date": "2030-10-20", "original_date": "2030-10-20",
43				"note": "年度例行校准", "created_at": createdAt, "status": calibrate.PlanStatusOpen,
44			}},
45		}
46		raw, err := json.MarshalIndent(data, "", "  ")
47		if err != nil {
48			t.Fatalf("序列化预置台账: %v", err)
49		}
50		if err := os.WriteFile(path, raw, 0o644); err != nil {
51			t.Fatalf("写入预置台账 %s: %v", path, err)
52		}
53	}
54	
55	// daysAgo / daysAfter 按本机日历返回相对运行当天的 YYYY-MM-DD。
56	func daysAgo(t *testing.T, n int) string {
57		t.Helper()
58		return time.Now().AddDate(0, 0, -n).Format(calibrate.DateLayout)
59	}
60	
61	func daysAfter(t *testing.T, n int) string {
62		t.Helper()
63		return time.Now().AddDate(0, 0, n).Format(calibrate.DateLayout)
64	}
