71	// completeJSONView 是 complete / review --json 中本测试关心的字段。
72	type completeJSONView struct {
73		Accepted   bool `json:"accepted"`
74		Idempotent bool `json:"idempotent"`
75		Plan       *struct {
76			Number            string `json:"number"`
77			Status            string `json:"status"`
78			CertificateNumber string `json:"certificate_number"`
79			CompletedAt       string `json:"completed_at"`
80		} `json:"plan"`
81	}
