83	// assertCompleteSuccess 核对完成成功在普通输出与 --json 下是同一业务结果：
84	// 退出码 0、计划已完成并保留指定证书编号与非空完成时间，且成功输出不得把
85	// 器具描述为已经可以使用。
86	func assertCompleteSuccess(t *testing.T, path, plan, cert string) {
87		t.Helper()
88		human := runArgs(t, "complete", "-f", path, "--number", plan, "--certificate", cert)
89		if human.code != 0 {
90			t.Fatalf("普通输出完成应退出 0，得到 %d，stderr=%s", human.code, human.stderr)
91		}
92		if !strings.Contains(human.stdout, "已完成：计划 "+plan) ||
93			!strings.Contains(human.stdout, "证书 "+cert) ||
94			!strings.Contains(human.stdout, "完成时间 ") {
95			t.Fatalf("普通输出应保留计划、证书编号与完成时间：%q", human.stdout)
96		}
97		if strings.Contains(human.stdout, "可以使用") ||
98			strings.Contains(human.stdout, "允许使用") ||
99			strings.Contains(human.stderr, "可以使用") ||
100			strings.Contains(human.stderr, "允许使用") {
101			t.Fatalf("完成计划的成功输出不得把器具描述为已经可以使用：stdout=%q stderr=%q",
102				human.stdout, human.stderr)
103		}
104	
105		js := runArgs(t, "complete", "-f", path, "--json", "--number", plan, "--certificate", cert)
106		if js.code != 0 {
107			t.Fatalf("--json 重复完成（幂等）应退出 0，得到 %d，stderr=%s", js.code, js.stderr)
108		}
109		var v completeJSONView
110		if err := json.Unmarshal([]byte(js.stdout), &v); err != nil {
111			t.Fatalf("complete JSON 解析失败: %v\n%s", err, js.stdout)
112		}
113		if !v.Accepted || !v.Idempotent || v.Plan == nil {
114			t.Fatalf("--json 幂等完成字段异常：%+v", v)
115		}
116		if v.Plan.Status != calibrate.PlanStatusDone ||
117			v.Plan.CertificateNumber != cert || v.Plan.CompletedAt == "" {
118			t.Fatalf("--json 计划应显示已完成并保留 %s 与完成时间：%+v", cert, v.Plan)
119		}
120		if strings.Contains(js.stdout, "可以使用") || strings.Contains(js.stdout, "允许使用") {
121			t.Fatalf("--json 成功输出不得暗示器具已经可以使用：%s", js.stdout)
122		}
123	}
124	
125	// assertPlanOpenInCLI 通过待办与按器具核对确认计划仍未完成、无完成时间与关联证书。
126	func assertPlanOpenInCLI(t *testing.T, path string) {
127		t.Helper()
128		tv := runArgs(t, "todos", "-f", path, "--json")
129		if tv.code != 0 || !strings.Contains(tv.stdout, `"count": 1`) ||
130			!strings.Contains(tv.stdout, "PL-1") {
131			t.Fatalf("计划应仍以未完成身份留在待办：code=%d stdout=%q", tv.code, tv.stdout)
132		}
133		rv := runArgs(t, "review", "--id", "M-1", "-f", path, "--json")
134		var v struct {
135			Plans []struct {
136				Status            string `json:"status"`
137				CompletedAt       string `json:"completed_at"`
138				CertificateNumber string `json:"certificate_number"`
139			} `json:"plans"`
140		}
141		if err := json.Unmarshal([]byte(rv.stdout), &v); err != nil {
142			t.Fatalf("review JSON 解析失败: %v\n%s", err, rv.stdout)
143		}
144		if len(v.Plans) != 1 || v.Plans[0].Status != calibrate.PlanStatusOpen ||
145			v.Plans[0].CompletedAt != "" || v.Plans[0].CertificateNumber != "" {
146			t.Fatalf("计划应继续未完成且无完成时间、关联证书：%+v", v.Plans)
147		}
148	}
