		}
		msg := err.Error()
		if !strings.Contains(msg, "2026-10-01") || !strings.Contains(msg, "建立日期 2026-10-02") {
			t.Fatalf("时区 %s 下拒绝原因应指出证书 10-01 早于计划建立日期 10-02，得到 %q",
				z.name, msg)
