		t.Fatalf("重复完成应幂等返回原完成时间：code=%d %+v", again.code, av)
	}
}

// TestCLICompleteCreatedDayWestOfUTC 命令行方向 2：建立时刻 -07:00 的 23:30
// 换算 UTC 已是次日。与建立本机日期同日的证书仍满足日期条件；早一天的证书
